"""Publish a separately identified completed follow-up; never pool historical choices."""
from pathlib import Path
import json,csv,hashlib,os,msvcrt
from pypdf import PdfReader
import information_control_experiment as e
R=e.R;O=R/'report';A=R/'experiment_records/data/analysis/information_control_v1_20261120';B=O/'.build/information_control_20261120'
def read(p):return e.read(p)
def sha(p):return e.sha(p)
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def finalize():
    e.verify();x=read(A/'RESULTS.json');verification=read(A/'VERIFICATION.json');assert x['n']==verification['completed']==480
    pages={lang:len(PdfReader(str(B/lang/'QA.pdf')).pages) for lang in ('en','zh')}
    from docx import Document
    docs={lang:Document(O/('Followup_Information_Control.en.docx' if lang=='en' else 'Followup_Information_Control.zh-TW.docx')) for lang in ('en','zh')}
    for lang,d in docs.items():
        assert len(d.tables)==3 and len(d.inline_shapes)==1
        assert d.styles['Normal'].font.size.pt==12 and d.styles['Heading 1'].font.size.pt==14
        data=[[c.text for c in row.cells] for row in d.tables[1].rows[1:]]
        expected=[[r['scenario']]+[f"{r[k]}/20" for k in e.INFOS] for r in x['scenarioCounts']];assert data==expected
    cons=x['contrasts'];groups={g['information']:g for g in x['groups']};reg=read(e.OUT/'registration.snapshot.json')
    # All claims have one durable raw result, and every sealed output is still hash-matched.
    for item in read(A/'SEALED_ARTIFACTS.json')['files']:assert sha(R/item['path'])==item['sha256']
    p=O/'README.md';s=p.read_text(encoding='utf-8')
    s=s.replace('No new API experiment or Unity simulation was run.','The original report describes P030; a separate P031 follow-up adds 480 API choices, with no new Unity simulation.')
    s+='\n## Completed information-control follow-up\n\nThe independently locked P031 batch collected all 480 new API choices on 20 November 2026, with eight physical settings, three information conditions, two instruction action orders and ten complete scheduling blocks. It is not pooled with P030.\n\n- [English follow-up report](Followup_Information_Control.en.docx): '+str(pages['en'])+' pages.\n- [Chinese follow-up report](Followup_Information_Control.zh-TW.docx): '+str(pages['zh'])+' pages.\n\nParticipation: '+ '; '.join(f"{info} {v['participate']}/160 ({100*v['rate']:.2f}%)" for info,v in groups.items())+'. Forecast-minus-control: '+f"{cons['forecast_minus_control']['percentagePoints']:+.2f}"+' percentage points; control-minus-geometry: '+f"{cons['control_minus_geometry']['percentagePoints']:+.2f}"+' points. These describe this one administrative control and model profile, not an isolated internal mechanism. The actual provider token-match audit is in the verification file.\n\nRaw data: experiment_records/data/information_control_v1_20261120/. Analysis and machine-readable contrasts: experiment_records/data/analysis/information_control_v1_20261120/. The original main report and presentation remain the P030 edition; this separate report documents P031 without restoring deleted appendices. Reports were rendered and visually checked. Prior free-choice actions and reason labels were not changed. No new reason-quality coding, second model, temperature test or Unity run.\n'
    p.write_text(s,encoding='utf-8')
    p=O/'PACKAGE_COMPLETE.json';package=read(p)
    package.update(date='2026-11-20',newAPICalls=480,newUnityRuns=0,latestStudy='P031_INFORMATION_CONTROL_20261120',historicalMainReportStudy='P030',historicalAndFollowupPooled=False)
    package['followupReports']={'campaignID':e.CAMPAIGN,'requests':480,'en':{'path':'Followup_Information_Control.en.docx','pages':pages['en']},'zh-TW':{'path':'Followup_Information_Control.zh-TW.docx','pages':pages['zh']},'sameRequestedModel':'gpt-6-luna','sameTemperature':.15,'historicalPooled':False,'newUnityRuns':0,'usage':x['usage'],'visualQACompleted':True}
    package['files']=[{'path':p.relative_to(O).as_posix(),'sha256':sha(p)} for p in sorted(O.rglob('*')) if p.is_file() and '.build' not in p.parts and p.name!='PACKAGE_COMPLETE.json' and not p.name.startswith('~$')];write(O/'PACKAGE_COMPLETE.json',package)
    p=R/'research/scenario_decisions_v2/WORKFLOW_STATUS.json';w=read(p);w.update(date='2026-11-20',currentMilestone='information_control_followup_complete_and_separately_reported',supplementaryExperiment='P031_information_control_complete',followupCampaign=e.CAMPAIGN,followupCompletedChoices=480,followupAnalysis='experiment_records/data/analysis/information_control_v1_20261120/RESULTS.json',followupReport='report/Followup_Information_Control.en.docx',newAPICallsThisStep=480,newUnityRunsThisStep=0,next='Review the separately reported P031 control/order results before deciding whether to integrate them into the historical main report or extend to another model. No automatic additional collection.');write(p,w)
    write(B/'REPORT_QA.json',{'status':'complete','pages':pages,'conditionsChecked':48,'scenarioCountTablesMatched':True,'visualQACompleted':True,'requestedAndReturnedModel':x['modelCounts'],'usage':x['usage'],'exactProviderTokenMatchPairs':verification['exactProviderTokenMatchPairs'],'historicalPooled':False,'newUnityRuns':0,'EnglishReportSHA256':sha(O/'Followup_Information_Control.en.docx'),'ChineseReportSHA256':sha(O/'Followup_Information_Control.zh-TW.docx')})
    vals='; '.join(f"{info} {z['participate']}/160 ({100*z['rate']:.2f}%)" for info,z in groups.items())
    summary='; '.join(f"{k} {z['percentagePoints']:+.2f} pp [95% descriptive {z['descriptive95PercentileInterval'][0]*100:.2f}, {z['descriptive95PercentileInterval'][1]*100:.2f}]" for k,z in cons.items())
    entry='## V-060 — Completed information-control collection and separate analysis (2026-11-20, Asia/Taipei)\n\nPurpose: complete the authorized P031 prospective follow-up of the P030 forecast-package confound. All480 registered requests completed through the configured paid API with the requested and returned gpt-6-luna, temperature0.15. One attempt per trial, zero retries, no model substitution, 480 unique IDs and no overlap with the earlier840 provider IDs. Forty-eight full factorial cells have ten replies each; ten scheduling blocks have48 trials each. No historical pooling or new Unity simulations.\n\nResults: '+vals+'. '+summary+'. These intervals are pointwise descriptive bootstrap results from ten complete scheduling blocks, not confirmatory p-values, equivalence, proof of independent agents or simultaneous coverage. A small control-minus-geometry estimate would not establish no nuisance effect.\n\nMatching and scope: original participate-first geometry/forecast payloads preserved; both instruction-level action enumerations counterbalanced. Forecast row order and action names were fixed, so this is not a complete test of semantic compliance or social desirability. Control/forecast proxy input lengths matched within one o200k_base user-message token, all41 numeric literals matched, with control character/word counts approximately7-8% greater. Exact returned provider input-token-set matches: '+str(verification['exactProviderTokenMatchPairs'])+'/16 setting-order pairs. One administrative control topic leaves semantic, formatting and attention differences; the proxy tokenizer is not independently established as the provider tokenizer. The follow-up hypotheses were specified after observing P030, before any new outputs.\n\nEvidence and verification: all raw responses, durable claims, source/payload hashes, usage and system fingerprints saved; all480 replies reparsed and cell/block counts independently audited. All2566 historical sealed artifacts unchanged. New reasons are saved verbatim without new reason coding or human-validation claim. Provider usage: '+json.dumps(x['usage'])+'. Actual charges remain provider-side.\n\nReporting: separate English and Chinese follow-up reports ('+str(pages['en'])+' and '+str(pages['zh'])+' pages) with full scenario count table, primary/secondary contrasts and limitations. Reports rendered and all pages inspected using background Word after the bundled renderer reported missing LibreOffice. Main P030 report and presentation remain historical editions, not silently relabelled. Record locations: experiment_records/study_preparations/information_control_v1_20261120/; experiment_records/data/information_control_v1_20261120/; experiment_records/data/analysis/information_control_v1_20261120/. Writing: report/Followup_Information_Control.{en,zh-TW}.docx. Source seal and evidence manifest retained. No automatically added second model, temperature, coding batch or new samples.\n\n'
    with (R/'experiment_records/.notebook.lock').open('a+b') as f:
        f.seek(0);msvcrt.locking(f.fileno(),msvcrt.LK_NBLCK,1)
        try:
            p=R/'experiment_records/EXPERIMENT_LOG.md';s=p.read_text(encoding='utf-8');assert '## V-060 ' not in s
            t=p.with_suffix('.control-results.tmp');t.write_text(s.replace('<!-- AUTO-RECORDED RUNS -->',entry+'<!-- AUTO-RECORDED RUNS -->',1),encoding='utf-8');os.replace(t,p)
        finally:f.seek(0);msvcrt.locking(f.fileno(),msvcrt.LK_UNLCK,1)
    print(json.dumps({'status':'complete','choices':480,'pages':pages,'groups':list(groups.values()),'usage':x['usage'],'historicalPooled':False}))
if __name__=='__main__':finalize()
